Seed Token (OpenCRVS → MOSIP).code:
// Send a token seed request to MOSIP after an OpenCRVS BIRTH_REGISTERED event.
request('/v1/tokenseeder/authtoken/json', {
  method: 'POST',
  data: {
    authdata: {
      authtype: 'demo',
      individualId: $.data.referenceTrackingId,
      individualIdType: 'UIN',
      // demographic + biographic fields lifted from the OpenCRVS FHIR bundle
      demographics: $.data.demographics,
    },
  },
});

Request Credential.code:
// Request a credential to be issued for a UIN.
request('/v1/credentialrequest/requestgenerator', {
  method: 'POST',
  data: {
    request: {
      credentialType: $.data.credentialType,
      issuer: $.configuration.partnerId,
      recepiant: $.configuration.partnerId,
      sharableAttributes: $.data.attributes,
      additionalData: { policyId: $.configuration.policyId },
      id: $.data.uin,
    },
  },
});

Subscribe to WebSub Topic.code:
// Subscribe to a MOSIP WebSub topic.
request($.configuration.webSubHubUrl, {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    'hub.callback': $.configuration.openfnWebhookUrl,
    'hub.mode': 'subscribe',
    'hub.topic': 'CREDENTIAL_ISSUED',
    'hub.secret': $.configuration.webSubSecret,
  }).toString(),
});
